#!/usr/bin/env python3
"""Apply RODRU's platform settings to folders generated by `flutter create`.

Idempotent: safe to run more than once.
  * Android: permissions, app name, <queries> for tel/sms/https, launcher icons
  * iOS: location / motion usage strings, URL schemes, display name
"""
import os
import plistlib
import re
import shutil
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
APP_NAME = "รอดรู้"


def patch_android():
    manifest = os.path.join(ROOT, "android/app/src/main/AndroidManifest.xml")
    if not os.path.exists(manifest):
        print("skip android: no manifest")
        return
    s = open(manifest, encoding="utf-8").read()

    perms = [
        "android.permission.INTERNET",
        "android.permission.ACCESS_COARSE_LOCATION",
        "android.permission.ACCESS_FINE_LOCATION",
    ]
    add = "".join(
        f'    <uses-permission android:name="{p}"/>\n' for p in perms if p not in s
    )
    if add:
        s = re.sub(r"(<manifest[^>]*>\s*\n)", lambda m: m.group(1) + add, s, count=1)

    s = re.sub(r'android:label="[^"]*"', f'android:label="{APP_NAME}"', s, count=1)

    intents = ""
    for scheme in ["tel", "sms", "https", "geo"]:
        if f'android:scheme="{scheme}"' not in s:
            action = "android.intent.action.DIAL" if scheme == "tel" else (
                "android.intent.action.SENDTO" if scheme == "sms" else "android.intent.action.VIEW")
            intents += (
                "        <intent>\n"
                f'            <action android:name="{action}"/>\n'
                f'            <data android:scheme="{scheme}"/>\n'
                "        </intent>\n"
            )
    if intents:
        if "<queries>" in s:
            s = s.replace("<queries>\n", "<queries>\n" + intents, 1)
        else:
            s = s.replace("</manifest>", "    <queries>\n" + intents + "    </queries>\n</manifest>")

    open(manifest, "w", encoding="utf-8").write(s)

    res = os.path.join(ROOT, "android/app/src/main/res")
    icons = os.path.join(ROOT, "tool/icons")
    for d in os.listdir(icons):
        src = os.path.join(icons, d, "ic_launcher.png")
        if d.startswith("mipmap-") and os.path.exists(src):
            os.makedirs(os.path.join(res, d), exist_ok=True)
            shutil.copy(src, os.path.join(res, d, "ic_launcher.png"))
    print("android patched")


def patch_ios():
    plist_path = os.path.join(ROOT, "ios/Runner/Info.plist")
    if not os.path.exists(plist_path):
        print("skip ios: no Info.plist")
        return
    with open(plist_path, "rb") as f:
        p = plistlib.load(f)
    p["CFBundleDisplayName"] = APP_NAME
    p["NSLocationWhenInUseUsageDescription"] = "ใช้ตำแหน่งเพื่อแสดงอากาศ ความเสี่ยง และจุดปลอดภัยใกล้คุณ (ไม่ส่งขึ้นเซิร์ฟเวอร์)"
    p["NSMotionUsageDescription"] = "ใช้เซนเซอร์เพื่อแสดงเข็มทิศทิศดวงอาทิตย์และดวงจันทร์"
    schemes = set(p.get("LSApplicationQueriesSchemes", []))
    schemes.update(["tel", "sms", "https", "comgooglemaps"])
    p["LSApplicationQueriesSchemes"] = sorted(schemes)
    with open(plist_path, "wb") as f:
        plistlib.dump(p, f)
    print("ios patched")


if __name__ == "__main__":
    patch_android()
    patch_ios()
    sys.exit(0)
